mapper.update:
update PTL_CASH_POSITION


        AMOUNT = AMOUNT + #{amount},


        CHL_FINPROD_ID = #{chlFinprodId,jdbcType=VARCHAR},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and ACCT_ID = #{acctId,jdbcType=VARCHAR}
and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
and CDATE = #{cdate,jdbcType=DATE}
and CCY = #{ccy,jdbcType=VARCHAR}

update ETR_CASH_POSITION


        AMOUNT =  AMOUNT + #{amount},


        CHL_FINPROD_ID = #{chlFinprodId,jdbcType=VARCHAR},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and ACCT_ID = #{acctId,jdbcType=VARCHAR}
and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
and CDATE = #{cdate,jdbcType=DATE}
and CCY = #{ccy,jdbcType=VARCHAR}

mapper.select:
SELECT PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY,sum(AMOUNT) AMOUNT FROM PTL_CASH_POSITION_FLOW WHERE ORDER_ID IN ( SELECT C.ORDER_ID FROM TRD_PRODUCT_TEMP_DEAL A, TRD_PRODUCT_TEMP_DEAL_ADD B, STL_PAY_TEMP_ORDERS C WHERE A.TRADE_ID = B.TRADE_ID AND A.TRADE_DATE = #{batchDate,jdbcType=DATE} AND A.TRADE_ID = C.TRADE_ID
#{tradeId,jdbcType=VARCHAR}
) GROUP BY PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY

SELECT PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY,sum(AMOUNT) AMOUNT FROM ETR_CASH_POSITION_FLOW WHERE ORDER_ID IN ( SELECT C.ORDER_ID FROM TRD_PRODUCT_TEMP_DEAL A, TRD_PRODUCT_TEMP_DEAL_ADD B, STL_PAY_TEMP_ORDERS C WHERE A.TRADE_ID = B.TRADE_ID AND A.TRADE_DATE = #{batchDate,jdbcType=DATE} AND A.TRADE_ID = C.TRADE_ID
#{tradeId,jdbcType=VARCHAR}
) GROUP BY PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY
